function doubleNumbers(numbers) {
    let doubled = [];
    for (let i = 0; i < numbers.length; i++) {
        doubled.push(numbers[i] * 2);
    }
    console.log(doubled);
}

// Casos de prueba:
doubleNumbers([1, 2, 3]); // Debe imprimir [2, 4, 6]
doubleNumbers([5, 10]); // Debe imprimir [10, 20]

